sys_ux_data_broker_transform.script:
function transform(input) {
    // List of properties to be fetched from the system properties
    var kpiProperties = [
        'sam.license.allocation.kpi',
        'sam.license.entitlement.kpi',
        'sam.license.contract.kpi'
    ];

    // Object to hold the KPI values for each type
    var kpiValues = {
        'allocation_kpi': [],
        'entitlement_kpi': [],
        'contract_kpi': []
    };

    // Function to fetch and parse the KPIs
    function fetchKPIs(propertyName) {
        var kpis = [];
        try {
            kpis = JSON.parse(gs.getProperty(propertyName)); // Parsing the JSON property
        } catch (e) {
            gs.log("Error parsing " + propertyName + ": " + e.message);
        }
        return kpis;
    }

    // Function to process each KPI and get the corresponding field value
    function processKPI(kpis, kpiType) {
        if (Array.isArray(kpis)) {
            kpis.forEach(function(kpi) {
                gs.log(kpiType + " Table: " + kpi.table + " Field: " + kpi.field + "Recommendation:" + kpi.recommendation); // Debug log
                if (kpi.kpi && kpi.table && kpi.field) {
                    var field_value = queryTableForField(kpi.table, kpi.field);
					var recommendation = (field_value > 0) ? kpi.recommendation : "No Action Need";
                    kpiValues[kpiType].push({
                        'kpi': kpi.kpi,
                        'table': kpi.table,
                        'field': kpi.field,
						'recommendation': recommendation,
                        'field_value': field_value,
						'description':kpi.description
                    });
                }
            });
        } else {
            gs.log("The " + kpiType + " property is not in the expected format.");
        }
    }

    // Loop through the KPI properties and process each one
    kpiProperties.forEach(function(property, index) {
        var kpiType = Object.keys(kpiValues)[index];
        var kpis = fetchKPIs(property);
        processKPI(kpis, kpiType);
    });

    // Function to query the table and get the field value dynamically
    function queryTableForField(tableName, fieldName) {
        try {
            var gr = new GlideRecord(tableName);
            gr.orderByDesc('sys_created_on'); // Sorting based on creation date (most recent first)
            gr.query();
            if (gr.next()) {
                return gr.getValue(fieldName);
            }
            return null;
        } catch (error) {
            gs.print("Error querying table: " + error.message);
            return null; // Return null in case of an error
        }
    }

    // Return the final KPI values object
    return kpiValues;
}
